import{_ as p,a0 as s,w as r,s as d,ao as a,I as e,a1 as o,A as l,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"什麼是 KDE Connect？怎麼用？ | LCTT x X-CMD","titleTemplate":false,"description":"什麼是 KDE Connect？怎麼用？ | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什麼是 KDE Connect？怎麼用？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什麼是 KDE Connect？怎麼用？ | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20220108 What is KDE Connect- How Do You Use It- [Beginner-s Guide]","title":"什麼是 KDE Connect？怎麼用？","tag":"202307","desc":""},"relativePath":"202307/20220108 What is KDE Connect- How Do You Use It- [Beginner-s Guide].md","filePath":"[post].md"}'),u={name:"202307/20220108 What is KDE Connect- How Do You Use It- [Beginner-s Guide].md"};function c(g,n,b,C,h,k){const i=s("Link");return r(),d("div",null,[n[22]||(n[22]=a('<h1 id="什麼是-kde-connect-怎麼用" tabindex="-1">什麼是 KDE Connect？怎麼用？ <a class="header-anchor" href="#什麼是-kde-connect-怎麼用" aria-label="Permalink to “什麼是 KDE Connect？怎麼用？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/22/141943rzv64oapavv7aa4o.jpg" alt=""></p><blockquote><p>什麼是 KDE Connect？它的主要特性是什麼？它應該如何安裝？本文提供了基本的使用指南。</p></blockquote><p>科技日新月異。有各種軟件、硬件和不同外形的設備。未來，不同設備之間將無縫集成，工作流程會跨越多個設備。每一天，我們都在向跨所有聯網設備發送和接收數據的狀態邁進。而 KDE Connect 就是引領 Linux 桌面系統向這一天進展的一面旗幟。</p><h3 id="什麼是-kde-connect" tabindex="-1">什麼是 KDE Connect？ <a class="header-anchor" href="#什麼是-kde-connect" aria-label="Permalink to “什麼是 KDE Connect？”">​</a></h3>',5)),e("p",null,[o(i,{href:"https://kdeconnect.kde.org/"},{default:l(()=>[...n[0]||(n[0]=[t("KDE Connect",-1)])]),_:1}),n[1]||(n[1]=t(" 是由 KDE 桌面團隊開發的，提供了 Linux 系統與其他系統，如 Windows、MacOS、Android 及 Linux，的無縫連接。",-1))]),n[23]||(n[23]=a('<p>KDE Connect 安裝後會使你擁有接收電話的通知、發送或接受短信、瀏覽文件、發送或接受文件等許多功能。</p><p>此外，KDE Connect 在無線網絡上遵循安全協議，以防止任何隱私泄露。它是自由開源的軟件，出現任何隱患的可能性微乎其微。組合了這些優良特性，KDE Connect 是一款出色的工具。</p><p>下文介紹你如何安裝和使用它。</p><h3 id="安裝-kde-connect" tabindex="-1">安裝 KDE Connect <a class="header-anchor" href="#安裝-kde-connect" aria-label="Permalink to “安裝 KDE Connect”">​</a></h3><p>本文將為你展示如何在 Linux 發行版和安卓智能手機之間連接。Windows 與安卓的連接也應是如此。</p><p>KDE Connect 的設置是一個雙向過程。你必須在你的 Linux 發行版和你的安卓智能手機都安裝 KDE Connect。</p><h4 id="在-linux-發行版上安裝" tabindex="-1">在 Linux 發行版上安裝 <a class="header-anchor" href="#在-linux-發行版上安裝" aria-label="Permalink to “在 Linux 發行版上安裝”">​</a></h4><p>在你的 Linux 發行版上安裝 KDE Connect 很簡單。其在所有的主流 Linux 發行版的官方倉庫中都可用。如果你在用 Ubuntu，並且想在終端安裝，運行如下指令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install kdeconnect</span></span></code></pre></div><p>Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install kdeconnect</span></span></code></pre></div><p>Arch Linux：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S kdeconnect</span></span></code></pre></div><p>或在 “<ruby>軟件<rt>Software</rt></ruby>” 應用中搜索並安裝。</p>',14)),e("p",null,[n[3]||(n[3]=t("對於 Windows 和其他 Linux 發行版，請參考 ",-1)),o(i,{href:"https://kdeconnect.kde.org/download.html"},{default:l(()=>[...n[2]||(n[2]=[t("這個頁面",-1)])]),_:1}),n[4]||(n[4]=t(" 的其他幾種下載安裝方式。",-1))]),n[24]||(n[24]=e("h4",{id:"在安卓智能手機上安裝",tabindex:"-1"},[t("在安卓智能手機上安裝 "),e("a",{class:"header-anchor",href:"#在安卓智能手機上安裝","aria-label":"Permalink to “在安卓智能手機上安裝”"},"​")],-1)),n[25]||(n[25]=e("p",null,"在安卓設備中，在谷歌 Play 商店中搜索 “KDE Connect” 並安裝。",-1)),e("blockquote",null,[e("p",null,[e("strong",null,[o(i,{href:"https://play.google.com/store/apps/details?id=org.kde.kdeconnect_tp&hl=en_IN&gl=US"},{default:l(()=>[...n[5]||(n[5]=[t("谷歌 Play 商店中的 KDE Connect",-1)])]),_:1})])])]),n[26]||(n[26]=e("p",null,"如果你在使用某個自由版本的安卓，你可以用下面的鏈接來通過 F-droid 安裝。（感謝我們的讀者提出這一條）。",-1)),e("blockquote",null,[e("p",null,[e("strong",null,[o(i,{href:"https://f-droid.org/en/packages/org.kde.kdeconnect_tp/"},{default:l(()=>[...n[6]||(n[6]=[t("F-droid 商店中的 KDE Connect",-1)])]),_:1})])])]),n[27]||(n[27]=a('<h3 id="設置-kde-connect" tabindex="-1">設置 KDE Connect <a class="header-anchor" href="#設置-kde-connect" aria-label="Permalink to “設置 KDE Connect”">​</a></h3><p>KDE Connect 可以連接相同網絡中的設備。因此，確保你的 Linux 系統和安卓設備都連接到了同一個無線網絡中。</p><p>打開你手機裏的 KDE Connect。你應該可以見到你的 Linux 系統的名稱。如果沒有看到任何內容，確保你的設備和 Linux 都連接到了同一個網絡後點擊“<ruby>刷新<rt>Refresh</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/01/KDE-Connect-in-Android-Device-showing-connected-Linux-System-1024x656.jpg" alt="安卓中的 KDE Connect 顯示連接到了 Linux 系統"></p><p>打開 Linux 中的 KDE Connect，你應當見到你的手機進入了下圖展示的樣子。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/01/KDE-Connect-before-pairing-1024x368.jpg" alt="配對前的 KDE Connect"></p><p>現在，點開你手機的名稱然後點擊 “<ruby>配對<rt>Pair</rt></ruby>”。</p><p>緊接着你的手機就會收到一個提醒：是否接受配對。選擇 “<ruby>接受<rt>Accept</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/01/Pairing-Request-for-KDE-Connect-1024x917.jpg" alt="KDE Connect 的配對請求"></p><p>代表你的手機的圖標應當轉為綠色 ，這表示你的手機和 Linux 系統都已經連接且配對。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/01/KDE-Connect-after-successful-pairing-1024x249.jpg" alt="成功配對後的 KDE Connect"></p><p>默認情況下，程序會開啓以下特性：</p><ul><li>多媒體控制</li><li>遠程輸入</li><li>遠程演示</li><li>搜尋設備</li><li>分享文件</li></ul><p>以下的特性需要你的安卓設備的額外權限。因為它們與隱私相關，這意味着你需要手動啓用它們。</p><ul><li>短信發送及接收</li><li>控制媒體播放器</li><li>手機上接受電腦的鍵盤輸入</li><li>提醒同步</li><li>來電提醒</li><li>聯繫人同步</li><li>接受鼠標操作</li></ul><p>對於這些特性，你需要去手動打開選項，並在安卓手機中授予權限。然後你就可以在 Linux 設備中享受這些服務了。</p><h3 id="示例-提醒同步" tabindex="-1">示例：提醒同步 <a class="header-anchor" href="#示例-提醒同步" aria-label="Permalink to “示例：提醒同步”">​</a></h3><p>我將為你演示提醒同步選項應在何處打開。打開你安卓手機中的 KDE Connect 程序，進入 “<ruby>已連接設備<rt>Connected Device</rt></ruby>” 部分。打開 “<ruby>提醒同步<rt>Notification Sync</rt></ruby>” 並選擇 “<ruby>打開設置應用<rt>OPEN SETTINGS</rt></ruby>”。</p><p>對 KDE Connect 啓用通知訪問，然後點擊 “<ruby>允許<rt>Allow</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/01/Enabling-Notification-Sync-1024x718.jpg" alt="打開同步提醒中"></p><p>之後將展示你手機上的提醒到你的 Linux 設備。例如，下面的提醒是我在我的測試安卓設備中收到的。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/01/Sample-Notification-in-Mobile-Phone-914x1024.jpg" alt="手機中的樣例提醒"></p><p>同樣的信息也展現在了 Linux 系統中的 KDE Connect。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/01/Sample-Notification-in-KDE-Connect-from-Mobile-Phone.jpg" alt="來自手機的樣例信息在 KDE Connect 中"></p><p>同樣地，在給 KDE Connect 權限後，你可以啓動對你可用的其他服務。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我希望這個指南可以幫助你在你的 Linux 系統和手機中設置 KDE Connect。</p><p>你可以在給與一些主要權限後，輕鬆地設置幾個特性，以使 KDE Connect 應用程序發揮最大優勢。配置完成後，你不再需要一直看你的手機。因為你可以在工作時輕易地在你的台式電腦或筆記本上閲讀提示、回消息。</p><p>你覺得 KDE Connect 怎麼樣？發在下面的評論框來讓我知道吧。</p><p><em>（題圖：MJ/5b09a037-14c3-4f62-a15a-dfd9fb2c7b3a）</em></p><hr>',31)),e("p",null,[n[8]||(n[8]=t("via: ",-1)),o(i,{href:"https://www.debugpoint.com/2022/01/kde-connect-guide/"},{default:l(()=>[...n[7]||(n[7]=[t("https://www.debugpoint.com/2022/01/kde-connect-guide/",-1)])]),_:1})]),e("p",null,[n[13]||(n[13]=t("作者：",-1)),o(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...n[9]||(n[9]=[t("Arindam",-1)])]),_:1}),n[14]||(n[14]=t(" 選題：",-1)),o(i,{href:"https://github.com/lkxed"},{default:l(()=>[...n[10]||(n[10]=[t("lkxed",-1)])]),_:1}),n[15]||(n[15]=t(" 譯者：",-1)),o(i,{href:"https://github.com/yjacks"},{default:l(()=>[...n[11]||(n[11]=[t("yjacks",-1)])]),_:1}),n[16]||(n[16]=t(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:l(()=>[...n[12]||(n[12]=[t("wxy",-1)])]),_:1})]),e("p",null,[n[19]||(n[19]=t("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...n[17]||(n[17]=[t("LCTT",-1)])]),_:1}),n[20]||(n[20]=t(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:l(()=>[...n[18]||(n[18]=[t("Linux中國",-1)])]),_:1}),n[21]||(n[21]=t(" 榮譽推出",-1))])])}const x=p(u,[["render",c]]);export{D as __pageData,x as default};
